#!/usr/bin/env bash
# P0 fixes round 2:
#   1) NEVER-HALT null action in the signal library -> accuracy SLO now holds
#      by construction (feasible set can no longer be empty)
#   2) corrected Proposition-2 validator (error-stickiness estimator; the v1
#      bound saturated at 1.0 and its rank correlation was an artifact)
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing P0 fixes round 2..."
decode "apply_null_action.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_prop2_validate.py" << 'B64EOF'

B64EOF
python apply_null_action.py && rm apply_null_action.py
echo ""
echo "Installed. Re-run the A/B and then regenerate all primary tables."